const es_webhook = Boolean($json.headers);

if (!es_webhook) {
  const fecha = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Guayaquil',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());

  return { json: { es_webhook: false, fecha, clave: '' } };
}

const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
let clave = '';
for (const [k, v] of Object.entries(headers)) {
  if (k.toLowerCase() === 'x-portika-clave') {
    clave = String(v ?? '');
    break;
  }
}

const rawFecha = $json.body?.fecha;
let fecha = null;
if (typeof rawFecha === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(rawFecha)) {
  const [y, m, d] = rawFecha.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (
    !Number.isNaN(dt.getTime()) &&
    dt.getUTCFullYear() === y &&
    dt.getUTCMonth() === m - 1 &&
    dt.getUTCDate() === d
  ) {
    fecha = rawFecha;
  }
}

return { json: { es_webhook: true, fecha, clave } };

const MESES = [
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
];

function formatearCodigos(codigos) {
  if (codigos.length === 1) return codigos[0];
  if (codigos.length === 2) return `${codigos[0]} y ${codigos[1]}`;
  return `${codigos.slice(0, -1).join(', ')} y ${codigos[codigos.length - 1]}`;
}

function formatearFechaEs(fechaIso) {
  const [, mesNum, diaNum] = String(fechaIso).split('-').map(Number);
  return `${diaNum} de ${MESES[mesNum - 1]}`;
}

const es_webhook = Boolean($('Entrada').first().json.es_webhook);
const filas = $input.all()
  .map((item) => item.json)
  .filter((row) => row.estudiante_codigo !== null && row.estudiante_codigo !== undefined);

const faltas_creadas = filas.length;
const grupos = new Map();

for (const fila of filas) {
  const rep = String(fila.representante_codigo);
  if (!grupos.has(rep)) {
    grupos.set(rep, {
      representante_codigo: rep,
      telegram_chat_id: fila.telegram_chat_id ? String(fila.telegram_chat_id).trim() : null,
      fecha: String(fila.fecha).slice(0, 10),
      estudiantes: [],
    });
  }
  grupos.get(rep).estudiantes.push(String(fila.estudiante_codigo));
}

let sin_contacto = 0;
const envios = [];

const representantesOrdenados = [...grupos.keys()].sort();
for (const rep of representantesOrdenados) {
  const grupo = grupos.get(rep);
  const estudiantesOrdenados = [...new Set(grupo.estudiantes)].sort();
  if (!grupo.telegram_chat_id) {
    sin_contacto += estudiantesOrdenados.length;
    continue;
  }
  const codigos = formatearCodigos(estudiantesOrdenados);
  const fechaTexto = formatearFechaEs(grupo.fecha);
  const mensaje = `Hola, en Pórtika no registramos el ingreso de ${codigos} hoy ${fechaTexto}. Si faltó por un motivo, respóndenos aquí con un texto, una nota de voz o la foto del justificativo.`;
  envios.push({
    representante_codigo: rep,
    telegram_chat_id: grupo.telegram_chat_id,
    estudiantes: estudiantesOrdenados,
    fecha: grupo.fecha,
    mensaje,
  });
}

return [
  {
    json: {
      es_webhook,
      faltas_creadas,
      mensajes_enviados: envios.length,
      sin_contacto,
      envios,
    },
  },
];
